template <typename T>
static T PickHandle(const std::vector<T>& pool, Decoder& d)
{
    if (pool.empty())
        return T{};

    const size_t index =
        static_cast<size_t>(d.ReadU16()) % pool.size();

    return pool[index];
}

template <typename T>
static void RememberHandle(std::vector<T>& pool, T value) {
    if (value && std::find(pool.begin(), pool.end(), value) == pool.end())
        pool.push_back(value);
}

